const fs = require('fs');
const j = JSON.parse(fs.readFileSync('/work/deliverable/q1_close.json','utf8'));
const m = j.months;
let ok = true;
for (const k of ["01","02","03"]) {
  const o = m[k];
  const otherSum = Object.values(o.other).reduce((a,b)=>a+b,0);
  const totalDebits = o.payroll + o.supplies + o.rent + otherSum;
  const net = +(o.revenue - totalDebits).toFixed(2);
  if (net !== +o.net_for_month.toFixed(2)) { ok=false; console.log("MISMATCH net", k, net, o.net_for_month); }
}
const q1rev = +(["01","02","03"].reduce((a,k)=>a+m[k].revenue,0)).toFixed(2);
const q1net = +(["01","02","03"].reduce((a,k)=>a+m[k].net_for_month,0)).toFixed(2);
console.log("Q1 revenue:", q1rev, "Q1 net:", q1net);
console.log("notes length:", j.notes.length);
console.log("contains 'no check payable to Nguyen'-style note:", /no check payable/i.test(j.notes));
console.log("contains '6 pay periods' note:", /pay periods/i.test(j.notes));
console.log("contains overdraft sequence:", /03\/12/.test(j.notes));
console.log("schema keys months:", Object.keys(m).join(","));
console.log("monthly fields present:", ["01","02","03"].every(k=>["revenue","payroll","supplies","rent","other","notes"].some(f=>k in m[k]) || true));
// check contract schema: months with revenue, payroll, supplies, rent, other{}, notes — does contract require per-month notes?
console.log("has top-level notes:", "notes" in j);
console.log("monthly 'notes' keys present:", ["01","02","03"].map(k=>k in m[k] && 'notes' in m[k]));
console.log("arithmetic ok:", ok);

